fn solve(queries: Vec<(i8, i8)>) -> Vec<i8> {
    // Helper function to compute S(k) = sum_{i=1}^k a[i].
    // According to the problem:
    // If k is even: S(k) = k / 2
    // If k is odd:  S(k) = -((k + 1) / 2)
    // For k = 0, S(0) = 0 by convention (sum over empty range).
    fn prefix_sum(k: i8) -> i8 {
        if k == 0 {
            0
        } else if k % 2 == 0 {
            k / 2
        } else {
            -((k as i16 + 1) / 2) as i8
        }
    }

    queries
        .into_iter()
        .map(|(l, r)| {
            // sum from l to r = S(r) - S(l - 1)
            prefix_sum(r) - prefix_sum(l - 1)
        })
        .collect()
}